package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen0Test {

    @Test
    public void testIsNumber_NullOrEmpty() {
        assertFalse(NumberUtils.isNumber(null));
        assertFalse(NumberUtils.isNumber(""));
    }

    @Test
    public void testIsNumber_Integers() {
        assertTrue(NumberUtils.isNumber("123"));
        assertTrue(NumberUtils.isNumber("0"));
        assertTrue(NumberUtils.isNumber("-123"));
        assertTrue(NumberUtils.isNumber("0123"));
    }

    @Test
    public void testIsNumber_Decimals() {
        assertTrue(NumberUtils.isNumber("123.45"));
        assertTrue(NumberUtils.isNumber(".45"));
        assertTrue(NumberUtils.isNumber("123."));
        assertFalse(NumberUtils.isNumber("."));
        assertFalse(NumberUtils.isNumber("1.2.3"));
    }

    @Test
    public void testIsNumber_ScientificNotation() {
        assertTrue(NumberUtils.isNumber("1e10"));
        assertTrue(NumberUtils.isNumber("1E10"));
        assertTrue(NumberUtils.isNumber("1.2E-10"));
        assertTrue(NumberUtils.isNumber("1.2e+10"));
        assertFalse(NumberUtils.isNumber("e10"));
        assertFalse(NumberUtils.isNumber("1e"));
        assertFalse(NumberUtils.isNumber("1e+"));
        assertFalse(NumberUtils.isNumber("1e1.2")); // decimal in exponent not allowed by logic
        assertFalse(NumberUtils.isNumber("1e1e1"));
    }

    @Test
    public void testIsNumber_Hexadecimal() {
        assertTrue(NumberUtils.isNumber("0x123"));
        assertTrue(NumberUtils.isNumber("0xABC"));
        assertTrue(NumberUtils.isNumber("0xabcdef"));
        assertTrue(NumberUtils.isNumber("0xABCDEF"));
        assertTrue(NumberUtils.isNumber("-0x123"));
        assertFalse(NumberUtils.isNumber("0x"));
        assertFalse(NumberUtils.isNumber("0xG"));
        assertFalse(NumberUtils.isNumber("0x12z"));
    }

    @Test
    public void testIsNumber_TypeQualifiers() {
        // d, D, f, F
        assertTrue(NumberUtils.isNumber("123d"));
        assertTrue(NumberUtils.isNumber("123D"));
        assertTrue(NumberUtils.isNumber("123f"));
        assertTrue(NumberUtils.isNumber("123F"));
        // l, L
        assertTrue(NumberUtils.isNumber("123l"));
        assertTrue(NumberUtils.isNumber("123L"));

        // Invalid qualifiers/combinations
        assertFalse(NumberUtils.isNumber("123z"));
        assertFalse(NumberUtils.isNumber("123.1l")); // L not allowed with decimal
        assertFalse(NumberUtils.isNumber("123e1l")); // L not allowed with exponent
        assertFalse(NumberUtils.isNumber("123.1L")); 
    }

    @Test
    public void testIsNumber_EdgeCasesAndInvalidStrings() {
        assertFalse(NumberUtils.isNumber("abc"));
        assertFalse(NumberUtils.isNumber("12a3"));
        assertFalse(NumberUtils.isNumber("+-123"));
        assertFalse(NumberUtils.isNumber("123--"));
        assertFalse(NumberUtils.isNumber("123+"));
        assertFalse(NumberUtils.isNumber("123-"));
        assertFalse(NumberUtils.isNumber("1.2e-"));
        assertFalse(NumberUtils.isNumber("1.2e+"));
        assertFalse(NumberUtils.isNumber("1.2e"));
        assertFalse(NumberUtils.isNumber("1.2.")); // redundant check
    }

    @Test
    public void testIsNumber_ComplexFlows() {
        // Testing the while loop condition (i < sz + 1 && allowSigns && !foundDigit)
        // This happens when string ends with e or E and we are looking for a sign
        assertFalse(NumberUtils.isNumber("123E"));
        assertFalse(NumberUtils.isNumber("123e-"));

        // Test single digit with sign
        assertTrue(NumberUtils.isNumber("-1"));
        assertTrue(NumberUtils.isNumber("+1"));

        // Test decimal with no leading digit
        assertTrue(NumberUtils.isNumber(".1"));

        // Test decimal with trailing dot and digit
        assertTrue(NumberUtils.isNumber("1."));
    }
}
